begin;
select plan(12);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select is((select shopping_default_period from cooksmith.household_settings where household_id='20000000-0000-4000-8000-000000000001'),'week','Existing households keep full-week default');
select lives_ok($$update cooksmith.household_settings set shopping_default_period='next3' where household_id='20000000-0000-4000-8000-000000000001'$$,'Owner changes usual preset');
select throws_ok($$update cooksmith.household_settings set shopping_default_period='custom'$$,'23514',null,'Default cannot be a stale custom range');
select throws_ok($$update cooksmith.household_settings set shopping_default_period='default'$$,'23514',null,'Default cannot reference itself');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select is((select shopping_default_period from cooksmith.household_settings),'next3','Active member reads default');
with changed as (update cooksmith.household_settings set shopping_default_period='next5' returning household_id) select is((select count(*) from changed),0::bigint,'Member cannot change owner-managed default');
select lives_ok($$insert into cooksmith.household_shopping_periods(household_id,shopping_period_kind,shopping_period_week,shopping_period_from,shopping_period_to) values('20000000-0000-4000-8000-000000000001','default','2026-10-05','2026-10-05','2026-10-11')$$,'Member may return current list to household default');
select is((select shopping_default_period from cooksmith.household_settings),'next3','Current choice does not rewrite default');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*) from cooksmith.household_settings where household_id='20000000-0000-4000-8000-000000000001'),0::bigint,'Unrelated household cannot read default');
with changed as (update cooksmith.household_settings set shopping_default_period='next5' where household_id='20000000-0000-4000-8000-000000000001' returning household_id) select is((select count(*) from changed),0::bigint,'Unrelated caller cannot change default');
reset role;
update cooksmith.household_members set status='inactive',inactive_at=now() where user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select is((select count(*) from cooksmith.household_settings where household_id='20000000-0000-4000-8000-000000000001'),0::bigint,'Inactive member loses default access');
reset role;
select ok(not has_table_privilege('anon','cooksmith.household_settings','select'),'Anonymous default reads denied');
select * from finish();
rollback;
